// Francés B1+: mismo formato que advanced_english_b1plus.js.
export const FRENCH_B1_PLUS=[
{id:'fr-01',level:'B1+',title:'Dos pronombres a la vez',goal:'usar dos pronombres en la misma frase.',
rule:'Cuando hay dos pronombres, el orden es fijo: me, te, nous, vous antes de le, la, les; estos antes de lui, leur; y al final y, en. Il me le donne, Je le lui donne, Je leur en parle. En passé composé van antes del auxiliar: Je le lui ai donné. En imperativo afirmativo van detrás: Donne-le-moi.',
items:[['Il me le donne.','Él me lo da.'],['Je le lui ai dit.','Se lo dije.'],['Je leur en parlerai.','Les hablaré de eso.'],['Donne-le-moi.','Dámelo.'],['Ne me le dis pas.','No me lo digas.'],['rendre','devolver'],['prêter','prestar'],['emprunter','pedir prestado']],
textTitle:'Le livre de Paul',text:[['Paul m’a prêté son livre le mois dernier.','Paul me prestó su libro el mes pasado.'],['Je le lui ai rendu hier, mais il l’a perdu.','Se lo devolví ayer, pero él lo perdió.'],['Sa sœur le lui avait offert pour Noël.','Su hermana se lo había regalado por Navidad.'],['Il ne le lui a pas encore dit.','Todavía no se lo ha dicho.'],['Je lui en ai acheté un autre.','Le compré otro.']],
questions:[['¿Quién regaló el libro?','La hermana de Paul','Un amigo','Su madre'],['¿Qué hizo el narrador?','Compró otro libro','Lo buscó','Se lo dijo a la hermana']],
drills:[['Reemplaza: Je donne le livre à Marie.','Je le lui donne.'],['Reemplaza: Il m’a envoyé la lettre.','Il me l’a envoyée.'],['Escribe en francés: «Dímelo.»','Dis-le-moi.']],
write:{prompt:'Cuenta un préstamo o regalo usando dos pronombres en al menos dos frases.',model:'Ma mère m’a offert une montre. Je la lui avais demandée. Je ne la prête à personne, mais je l’ai montrée à mes amis.'}},
{id:'fr-02',level:'B1+',title:'Si ya hubiera ocurrido antes',goal:'narrar con plus-que-parfait y concordancia de tiempos.',
rule:'Al contar en pasado, los tiempos se desplazan. Presente pasa a imparfait; passé composé, a plus-que-parfait; futuro, a conditionnel. Il a dit qu’il était fatigué, qu’il avait dormi mal, qu’il viendrait. Las marcas también cambian: demain pasa a le lendemain; hier, a la veille.',
items:[['Il a dit qu’il était fatigué.','Dijo que estaba cansado.'],['Elle m’a dit qu’elle viendrait.','Me dijo que vendría.'],['Je savais qu’il était parti.','Sabía que se había ido.'],['Il a demandé si j’étais prêt.','Preguntó si estaba listo.'],['le lendemain','al día siguiente'],['la veille','la víspera'],['annoncer','anunciar'],['promettre','prometer']],
textTitle:'La promesse',text:[['Mon patron m’a annoncé que l’entreprise allait déménager.','Mi jefe me anunció que la empresa iba a mudarse.'],['Il a dit qu’il avait trouvé un bureau à Lyon.','Dijo que había encontrado una oficina en Lyon.'],['Il a promis que personne ne perdrait son travail.','Prometió que nadie perdería su trabajo.'],['La veille, je ne savais encore rien.','La víspera aún no sabía nada.'],['Le lendemain, tout le monde en parlait.','Al día siguiente, todos hablaban de eso.']],
questions:[['¿Adónde se muda la empresa?','A Lyon','A París','A Marsella'],['¿Qué prometió?','Nadie perdería su trabajo','Más sueldo','Oficinas nuevas']],
drills:[['Pasa a indirecto: « Je suis malade », a-t-il dit.','Il a dit qu’il était malade.'],['Pasa a indirecto: « Je viendrai », a-t-elle dit.','Elle a dit qu’elle viendrait.'],['Pasa a indirecto: « J’ai fini », a-t-il dit.','Il a dit qu’il avait fini.']],
write:{prompt:'Resume una conversación reciente en pasado.',model:'Ma sœur m’a dit qu’elle avait trouvé un travail. Elle a ajouté qu’elle déménagerait bientôt. Je lui ai dit que j’étais très content.'}},
{id:'fr-03',level:'B1+',title:'Hacer énfasis',goal:'destacar una idea como un francés.',
rule:'Para destacar se usa la mise en relief. C’est … qui para el sujeto: C’est Marie qui a appelé. C’est … que para lo demás: C’est demain que je pars. Ce qui … c’est, ce que … c’est: Ce que je veux, c’est dormir. Tras moi, toi, el verbo concuerda: C’est moi qui suis arrivé.',
items:[['C’est Marie qui a appelé.','Fue Marie quien llamó.'],['C’est demain que je pars.','Es mañana cuando me voy.'],['Ce que je veux, c’est dormir.','Lo que quiero es dormir.'],['Ce qui me plaît, c’est le calme.','Lo que me gusta es la calma.'],['C’est moi qui ai raison.','Soy yo quien tiene razón.'],['surtout','sobre todo'],['justement','precisamente'],['au fond','en el fondo']],
textTitle:'Ce qui compte vraiment',text:[['Ce qui m’a surpris dans ce travail, ce sont les gens.','Lo que me sorprendió de este trabajo es la gente.'],['C’est mon premier chef qui m’a appris à écouter.','Fue mi primer jefe quien me enseñó a escuchar.'],['Ce que je préfère, c’est travailler en équipe.','Lo que prefiero es trabajar en equipo.'],['Les horaires étaient difficiles, mais c’est justement pour ça que j’ai appris.','Los horarios eran difíciles, pero precisamente por eso aprendí.'],['Au fond, c’est avec qui on travaille qui compte.','En el fondo, lo que cuenta es con quién trabajas.']],
questions:[['¿Qué le enseñó su jefe?','A escuchar','A vender','A escribir'],['¿Qué prefiere?','Trabajar en equipo','Trabajar solo','Los horarios']],
drills:[['Destaca: Paul a cassé le verre.','C’est Paul qui a cassé le verre.'],['Destaca: Je veux un café. → Ce que ___','Ce que je veux, c’est un café.'],['Corrige: C’est moi qui a raison.','C’est moi qui ai raison.']],
write:{prompt:'Escribe qué valoras más en la amistad usando estas estructuras.',model:'Ce que j’aime chez mes amis, c’est leur honnêteté. C’est ma meilleure amie qui m’a aidé. Ce qui compte, c’est la confiance.'}},
{id:'fr-04',level:'B1+',title:'El subjuntivo sin miedo',goal:'decidir cuándo va subjuntivo.',
rule:'Va subjuntivo tras il faut que, vouloir que, bien que, pour que, avant que, avoir peur que, douter que y tras opiniones negativas: je ne crois pas que. No va con espérer que, penser que, après que, ni si: J’espère qu’il viendra. Si el sujeto es el mismo se usa infinitivo: Je veux partir, no «je veux que je parte».',
items:[['Il faut que tu partes.','Tienes que irte.'],['Bien qu’il soit tard, je reste.','Aunque es tarde, me quedo.'],['Je ne crois pas qu’il vienne.','No creo que venga.'],['J’espère qu’il viendra.','Espero que venga.'],['Je t’explique pour que tu comprennes.','Te lo explico para que entiendas.'],['avant que','antes de que'],['à moins que','a menos que'],['douter','dudar']],
textTitle:'Avant le départ',text:[['Il faut que nous partions avant qu’il fasse nuit.','Tenemos que irnos antes de que anochezca.'],['Bien que la route soit longue, je ne suis pas inquiet.','Aunque la ruta es larga, no estoy preocupado.'],['Je ne crois pas qu’il y ait beaucoup de circulation.','No creo que haya mucho tráfico.'],['J’espère que nous arriverons pour le dîner.','Espero que lleguemos para la cena.'],['Appelle tes parents pour qu’ils sachent où nous sommes.','Llama a tus padres para que sepan dónde estamos.']],
questions:[['¿Cuándo deben irse?','Antes de anochecer','Por la mañana','Mañana'],['¿Por qué llamar a los padres?','Para que sepan dónde están','Para pedir dinero','Para cenar']],
drills:[['Completa: Il faut que tu ___ (être) là.','sois'],['Completa: J’espère qu’il ___ (venir, futuro).','viendra'],['Completa: Bien qu’elle ___ (avoir) peu de temps, elle aide.','ait']],
write:{prompt:'Da tres consejos a un amigo que se muda, usando il faut que.',model:'Il faut que tu trouves un appartement. Je ne crois pas que ce soit difficile. J’espère que tu seras heureux là-bas.'}},
{id:'fr-05',level:'B1+',title:'Pude haber hecho',goal:'expresar lamentos y reproches.',
rule:'El conditionnel passé es avoir o être en condicional + participio: J’aurais aimé, Je serais venu. Con devoir y pouvoir expresa lamento o reproche: J’aurais dû t’appeler, Tu aurais pu me le dire. Si + plus-que-parfait + conditionnel passé: Si j’avais su, je serais venu. Nunca condicional tras si.',
items:[['Si j’avais su, je serais venu.','Si lo hubiera sabido, habría venido.'],['J’aurais dû t’appeler.','Debí llamarte.'],['Tu aurais pu me le dire.','Podrías habérmelo dicho.'],['J’aurais aimé rester.','Me habría gustado quedarme.'],['regretter','lamentar'],['une occasion','una oportunidad'],['refuser','rechazar'],['en vouloir à quelqu’un','guardar rencor a alguien']],
textTitle:'L’occasion manquée',text:[['Il y a cinq ans, on m’a proposé un poste à Montréal.','Hace cinco años me ofrecieron un puesto en Montreal.'],['J’ai refusé parce que j’avais peur.','Lo rechacé porque tenía miedo.'],['Si j’avais accepté, j’aurais beaucoup appris.','Si hubiera aceptado, habría aprendido mucho.'],['Mais je n’aurais pas rencontré ma femme.','Pero no habría conocido a mi esposa.'],['Finalement, je ne regrette rien.','Al final, no lamento nada.']],
questions:[['¿Por qué rechazó?','Tenía miedo','Ganaba poco','Estaba enfermo'],['¿Lamenta su decisión?','No','Sí','Mucho']],
drills:[['Completa: Si tu ___ (venir, plus-que-parfait), tu l’aurais vu.','étais venu','étais venue'],['Escribe en francés: «Debí estudiar.»','J’aurais dû étudier.'],['Corrige: Si j’aurais su, je serais venu.','Si j’avais su, je serais venu.']],
write:{prompt:'¿Qué habría pasado si hubieras elegido otro camino?',model:'Si j’avais étudié la médecine, je serais resté dans ma ville. Je n’aurais pas rencontré mes amis. Je ne regrette pas mon choix.'}},
{id:'fr-06',level:'B1+',title:'Pasiva y alternativas',goal:'elegir entre pasiva, on y se.',
rule:'La pasiva es être + participio, que concuerda: La maison a été vendue. En el habla el francés prefiere on: On a vendu la maison, o se: Ce vin se boit frais. Se faire + infinitivo indica que alguien te hace algo: Je me suis fait voler mon sac, me robaron el bolso. Faire + infinitivo es mandar hacer: Je fais réparer ma voiture.',
items:[['La maison a été vendue.','La casa fue vendida.'],['On a fermé la route.','Cerraron la carretera.'],['Ce vin se boit frais.','Este vino se bebe frío.'],['Je me suis fait voler mon sac.','Me robaron el bolso.'],['Je fais réparer ma voiture.','Mando a reparar mi coche.'],['construire','construir'],['détruire','destruir'],['ouvrir au public','abrir al público']],
textTitle:'Un vieux pont',text:[['Ce pont a été construit en 1890.','Este puente se construyó en 1890.'],['Il a été presque détruit pendant la guerre.','Fue casi destruido durante la guerra.'],['On l’a réparé l’année dernière.','Lo repararon el año pasado.'],['Il a été rouvert au public en mai.','Se reabrió al público en mayo.'],['Aujourd’hui, il se visite gratuitement.','Hoy se visita gratis.']],
questions:[['¿Cuándo se construyó?','En 1890','En mayo','Durante la guerra'],['¿Cuánto cuesta visitarlo?','Es gratis','Mucho','Cinco euros']],
drills:[['Pasa a pasiva: On a volé la voiture.','La voiture a été volée.'],['Escribe en francés: «Mando a cortar mi pelo.»','Je me fais couper les cheveux.'],['Pasa a pasiva: On construira un pont.','Un pont sera construit.']],
write:{prompt:'Explica la historia de un edificio con pasiva y on.',model:'Cette église a été construite il y a trois cents ans. On l’a réparée deux fois. Aujourd’hui, elle est visitée par beaucoup de touristes.'}},
{id:'fr-07',level:'B1+',title:'Hablar por escrito',goal:'distinguir registro formal e informal.',
rule:'Formal: nous en vez de on, inversión (Pourriez-vous ?), ne completo, cependant, afin de. Informal: on, je sais pas, mais, pour. Correo: Madame, Monsieur, ; Je vous écris au sujet de ; Je vous prie d’agréer, Madame, l’expression de mes salutations distinguées. En un correo normal basta Cordialement. Bien cordialement entre conocidos.',
items:[['Madame, Monsieur,','Estimada señora, estimado señor:'],['Je vous écris au sujet de votre annonce.','Le escribo por su anuncio.'],['Pourriez-vous me donner des informations ?','¿Podría darme información?'],['Veuillez trouver ci-joint mon CV.','Adjunto mi CV.'],['Dans l’attente de votre réponse,','A la espera de su respuesta,'],['Cordialement','Atentamente'],['le poste','el puesto'],['une candidature','una candidatura']],
textTitle:'Une candidature',text:[['Madame, Monsieur,','Estimada señora, estimado señor:'],['Je vous écris au sujet du poste d’assistante.','Le escribo por el puesto de asistente.'],['J’ai cinq ans d’expérience dans le service client.','Tengo cinco años de experiencia en atención al cliente.'],['Veuillez trouver ci-joint mon CV.','Adjunto mi CV.'],['Dans l’attente de votre réponse, je vous prie d’agréer mes salutations distinguées.','A la espera de su respuesta, le saluda atentamente.']],
questions:[['¿Qué puesto solicita?','Asistente','Directora','Profesora'],['¿Qué adjunta?','Su CV','Una factura','Un contrato']],
drills:[['Hazlo formal: Tu peux m’envoyer ça ?','Pourriez-vous m’envoyer cela ?'],['Escribe el cierre corto de un correo:','Cordialement'],['Escribe en francés: «Adjunto mi CV.»','Veuillez trouver ci-joint mon CV.','Vous trouverez ci-joint mon CV.']],
write:{prompt:'Escribe un correo formal pidiendo información sobre un curso.',model:'Madame, Monsieur, je vous écris au sujet de votre cours de français. Pourriez-vous m’envoyer les tarifs ? Dans l’attente de votre réponse. Cordialement, Ana Ruiz'}},
{id:'fr-08',level:'B1+',title:'Reclamar',goal:'presentar una queja firme y cortés.',
rule:'Hecho, problema, petición. Je souhaite déposer une réclamation. Malheureusement, l’appareil ne fonctionne pas. Je vous demande de me rembourser. Se plaindre de: quejarse de. Demander de + infinitivo: pedir hacer. Evita acusar directamente: Le colis est arrivé abîmé. Je ne suis pas satisfait suena firme sin ser grosero.',
items:[['Je souhaite déposer une réclamation.','Deseo presentar una queja.'],['Le colis est arrivé abîmé.','El paquete llegó dañado.'],['Je vous demande de me rembourser.','Le pido que me reembolse.'],['Je ne suis pas satisfait.','No estoy satisfecho.'],['un remboursement','un reembolso'],['la facture','la factura'],['échanger','cambiar'],['déçu','decepcionado']],
textTitle:'Une réclamation',text:[['Le 3 mars, j’ai commandé un ordinateur sur votre site.','El 3 de marzo pedí un ordenador en su web.'],['Malheureusement, le colis est arrivé abîmé.','Por desgracia, el paquete llegó dañado.'],['J’ai appelé deux fois sans obtenir de réponse.','Llamé dos veces sin obtener respuesta.'],['Je suis très déçu par votre service.','Estoy muy decepcionado con su servicio.'],['Je vous demande de me rembourser sous sept jours.','Le pido que me reembolse en siete días.']],
questions:[['¿Qué le pasó al paquete?','Llegó dañado','No llegó','Era otro'],['¿Qué pide?','Un reembolso','Otro ordenador','Una disculpa']],
drills:[['Escribe en francés: «Quiero cambiar este producto.»','Je voudrais échanger ce produit.','Je souhaite échanger ce produit.'],['Completa: Je me plains ___ service.','du'],['Completa: Je vous demande ___ répondre.','de']],
write:{prompt:'Escribe una queja a un hotel.',model:'Madame, Monsieur, j’ai séjourné dans votre hôtel la semaine dernière. Malheureusement, la chambre était sale. Je vous demande un remboursement partiel. Cordialement'}},
{id:'fr-09',level:'B1+',title:'Argumentar',goal:'defender una opinión de forma ordenada.',
rule:'Opinión: À mon avis, Selon moi, Il me semble que. Razón: La raison principale est que. Ejemplo: Par exemple. Objeción: Certains pensent que. Concesión: Certes … mais. Conclusión: En somme, Pour conclure. Il me semble que lleva indicativo; il ne me semble pas que, subjuntivo. D’une part … d’autre part ordena los dos lados.',
items:[['À mon avis, c’est une erreur.','En mi opinión, es un error.'],['La raison principale est le coût.','La razón principal es el coste.'],['Certains pensent que c’est nécessaire.','Algunos piensan que es necesario.'],['Certes, c’est cher, mais c’est utile.','Es cierto que es caro, pero es útil.'],['D’une part … d’autre part','por una parte … por otra'],['En somme, je suis contre.','En suma, estoy en contra.'],['un avantage','una ventaja'],['un inconvénient','un inconveniente']],
textTitle:'Interdire les voitures ?',text:[['À mon avis, il faut interdire les voitures en centre-ville.','En mi opinión, hay que prohibir los coches en el centro.'],['La raison principale est la pollution.','La razón principal es la contaminación.'],['Certains pensent que les commerces perdront des clients.','Algunos piensan que los comercios perderán clientes.'],['Certes, c’est un risque, mais les rues calmes attirent les visiteurs.','Es cierto que es un riesgo, pero las calles tranquilas atraen visitantes.'],['En somme, les avantages l’emportent sur les inconvénients.','En suma, las ventajas superan a los inconvenientes.']],
questions:[['¿Qué defiende?','Prohibir los coches','Más parkings','Cerrar comercios'],['¿Qué atraen las calles tranquilas?','Visitantes','Coches','Ruido']],
drills:[['Escribe en francés: «Estoy en contra.»','Je suis contre.'],['Completa: ___, c’est cher, mais c’est utile.','Certes'],['Escribe en francés: «por una parte»','d’une part']],
write:{prompt:'¿Deberíamos trabajar cuatro días a la semana? Argumenta.',model:'À mon avis, la semaine de quatre jours serait positive. La raison principale est la santé. Certes, cela coûte cher, mais les gens seraient plus efficaces. En somme, je suis pour.'}},
{id:'fr-10',level:'B1+',title:'Conectores finos',goal:'unir ideas con precisión.',
rule:'Causa: car, puisque (causa conocida), comme (al inicio), en raison de + nombre. Consecuencia: donc, c’est pourquoi, si bien que, par conséquent. Oposición: pourtant, cependant, alors que, malgré + nombre. Finalidad: afin de + infinitivo, pour que + subjuntivo. Puisque no equivale a parce que: supone que el otro ya lo sabe.',
items:[['Comme il pleut, je reste.','Como llueve, me quedo.'],['Puisque tu es là, aide-moi.','Ya que estás aquí, ayúdame.'],['Il a raté le train, c’est pourquoi il est en retard.','Perdió el tren, por eso llega tarde.'],['Malgré la pluie, nous sommes sortis.','A pesar de la lluvia, salimos.'],['Afin de réussir, il faut travailler.','Para tener éxito hay que trabajar.'],['par conséquent','por consiguiente'],['pourtant','sin embargo'],['en raison de','debido a']],
textTitle:'Le télétravail',text:[['Beaucoup de salariés préfèrent le télétravail en raison de sa flexibilité.','Muchos empleados prefieren el teletrabajo debido a su flexibilidad.'],['Pourtant, on peut s’y sentir seul.','Sin embargo, uno puede sentirse solo.'],['Malgré ces problèmes, la plupart ne veulent pas revenir.','A pesar de esos problemas, la mayoría no quiere volver.'],['Comme les entreprises s’inquiètent, elles cherchent un équilibre.','Como las empresas se preocupan, buscan un equilibrio.'],['Par conséquent, beaucoup proposent un système mixte.','Por consiguiente, muchas proponen un sistema mixto.']],
questions:[['¿Por qué prefieren el teletrabajo?','Por la flexibilidad','Por el sueldo','Por el jefe'],['¿Qué proponen las empresas?','Un sistema mixto','Volver todos','Cerrar oficinas']],
drills:[['Elige malgré o bien que: ___ le froid, il sort.','Malgré'],['Elige comme o parce que al inicio: ___ il est tard, je pars.','Comme'],['Escribe en francés: «por eso»','c’est pourquoi']],
write:{prompt:'Escribe ventajas y desventajas de vivir en una gran ciudad con conectores.',model:'Comme les loyers sont élevés, beaucoup partent. Pourtant, il y a plus d’opportunités. Malgré le bruit, je préfère la ville.'}},
{id:'fr-11',level:'B1+',title:'Faux amis',goal:'evitar los errores típicos de un hispanohablante.',
rule:'Parecen iguales y no lo son. Constipé = estreñido, resfriado es enrhumé. Embrasser = besar, abrazar es serrer dans ses bras. Attendre = esperar, atender es s’occuper de. Rester = quedarse. Sortir = salir. Le mari = marido; la mer = mar, femenino. Le lait, le sel son masculinos; la dent, femenino. Quitter = dejar a alguien o un lugar. Salir en francés significa ensuciar.',
items:[['Je suis enrhumé.','Estoy resfriado.'],['Il l’a serrée dans ses bras.','La abrazó.'],['Je t’attends ici.','Te espero aquí.'],['J’ai quitté Paris.','Me fui de París.'],['Je reste à la maison.','Me quedo en casa.'],['la dent','el diente'],['le lait','la leche'],['la mer','el mar']],
textTitle:'Quelle honte !',text:[['À mon arrivée en France, j’ai dit à mon médecin que j’étais constipé.','Al llegar a Francia, le dije a mi médico que estaba estreñido.'],['En réalité, je voulais dire que j’étais enrhumé.','En realidad quería decir que estaba resfriado.'],['Il m’a regardé avec un sourire.','Me miró con una sonrisa.'],['Depuis, je vérifie chaque mot.','Desde entonces reviso cada palabra.'],['Et je ne dis plus jamais que je vais embrasser mes collègues !','¡Y nunca más digo que voy a besar a mis colegas!']],
questions:[['¿Qué quiso decir?','Que estaba resfriado','Que estaba estreñido','Que tenía hambre'],['¿Qué hace desde entonces?','Revisa cada palabra','Evita al médico','Habla menos']],
drills:[['Traduce: «Estoy resfriado.»','Je suis enrhumé.','Je suis enrhumée.'],['Escribe en francés: «Te espero.»','Je t’attends.'],['Género de mar: ___ mer','la']],
write:{prompt:'Escribe cuatro frases con attendre, quitter, rester y enrhumé.',model:'Je t’attends depuis une heure. J’ai quitté mon travail en mars. Je reste à la maison parce que je suis enrhumé.'}},
{id:'fr-12',level:'B1+',title:'Contar con estilo',goal:'contar una anécdota con el passé simple reconocido.',
rule:'En novelas aparece el passé simple: il fut, elle alla, ils firent. No se usa al hablar, pero debes reconocerlo: equivale al passé composé. Para contar en oral: Figure-toi que (imagínate que), Tout à coup, Heureusement, Finalement. Reacciones: Sans blague ! Ce n’est pas vrai ! Intensifica: complètement épuisé, vraiment.',
items:[['Figure-toi que j’ai vu Marie !','¡Imagínate que vi a Marie!'],['Tout à coup, la lumière s’est éteinte.','De repente se apagó la luz.'],['Heureusement, un technicien est arrivé.','Por suerte, llegó un técnico.'],['Sans blague !','¡No me digas!'],['Il entra et ferma la porte.','Entró y cerró la puerta.'],['épuisé','agotado'],['l’ascenseur','el ascensor'],['par hasard','por casualidad']],
textTitle:'Dans l’ascenseur',text:[['Figure-toi que vendredi, je suis resté bloqué dans l’ascenseur.','Imagínate que el viernes me quedé atrapado en el ascensor.'],['Tout à coup, la lumière s’est éteinte.','De repente se apagó la luz.'],['Évidemment, mon téléphone n’avait pas de réseau.','Por supuesto, mi teléfono no tenía cobertura.'],['Heureusement, un technicien est arrivé après deux heures.','Por suerte, llegó un técnico tras dos horas.'],['J’étais complètement épuisé.','Estaba completamente agotado.']],
questions:[['¿Dónde se quedó?','En el ascensor','En el metro','En casa'],['¿Cuánto esperó?','Dos horas','Diez minutos','Toda la noche']],
drills:[['Da el passé composé de «il alla»:','il est allé'],['Escribe en francés: «De repente»','Tout à coup','Soudain'],['Escribe en francés: «por casualidad»','par hasard']],
write:{prompt:'Cuenta la historia más rara que te haya pasado.',model:'Figure-toi que j’ai rencontré mon ancienne prof à l’aéroport. Tout à coup, elle m’a appelé. Heureusement, je l’ai reconnue.'}},
{id:'fr-13',level:'B1+',title:'Describir datos',goal:'presentar cifras y resumir un texto.',
rule:'Cifras: augmenter, baisser, rester stable. De indica la diferencia: a augmenté de 5 %. À indica el resultado: est passé à 20 %. Partes: la moitié, un tiers, la plupart de. Resumir: Ce texte traite de, L’auteur affirme que, En résumé. Tras la plupart de el verbo va en plural: La plupart des gens pensent.',
items:[['Les prix ont augmenté de cinq pour cent.','Los precios subieron un cinco por ciento.'],['La moitié des personnes sont d’accord.','La mitad de las personas está de acuerdo.'],['La plupart des gens pensent ainsi.','La mayoría de la gente piensa así.'],['Ce texte traite du travail.','Este texto trata del trabajo.'],['En résumé, cela aide.','En resumen, ayuda.'],['environ','aproximadamente'],['un tiers','un tercio'],['par rapport à','en comparación con']],
textTitle:'Le rapport annuel',text:[['Le rapport montre que les ventes en ligne ont augmenté de douze pour cent.','El informe muestra que las ventas online subieron un doce por ciento.'],['Dans les magasins, elles sont restées stables.','En las tiendas se mantuvieron estables.'],['Environ un tiers des clients achètent avec leur téléphone.','Aproximadamente un tercio de los clientes compra con el teléfono.'],['Pour la plupart, le délai de livraison est essentiel.','Para la mayoría, el plazo de entrega es esencial.'],['En résumé, la rapidité décidera du marché.','En resumen, la rapidez decidirá el mercado.']],
questions:[['¿Cuánto subieron las ventas online?','Un doce por ciento','Un tercio','La mitad'],['¿Qué decidirá el mercado?','La rapidez','El precio','La marca']],
drills:[['Elige de o à: Le prix a augmenté ___ 10 %.','de'],['Escribe en francés: «la mitad»','la moitié'],['Corrige: La plupart des gens pense ainsi.','La plupart des gens pensent ainsi.']],
write:{prompt:'Resume el texto de hoy en tres frases.',model:'Ce texte traite des ventes en ligne. Elles ont fortement augmenté. En résumé, le délai de livraison est le facteur le plus important.'}},
{id:'fr-14',level:'B1+',title:'Reuniones y acuerdos',goal:'intervenir en una reunión y negociar.',
rule:'Intervenir: Excusez-moi de vous interrompre. Aclarar: Ce que je veux dire, c’est que… Proponer: Et si on partageait ? (si + imparfait). Negociar: D’accord, à condition que + subjuntivo. Ceder: Ça me va. Cerrar: Pour résumer. Et si + imparfait propone con suavidad. À condition de + infinitivo si el sujeto es el mismo.',
items:[['Excusez-moi de vous interrompre.','Perdón por interrumpir.'],['Et si on partageait les frais ?','¿Y si dividimos los gastos?'],['D’accord, à condition que ce soit écrit.','De acuerdo, con la condición de que sea por escrito.'],['Ça me va.','Me parece bien.'],['Pour résumer, on commence en mai.','Para resumir, empezamos en mayo.'],['un compromis','un acuerdo'],['une offre','una oferta'],['une proposition','una propuesta']],
textTitle:'Une négociation',text:[['Notre offre est de dix mille euros.','Nuestra oferta es de diez mil euros.'],['C’est moins que ce que nous espérions.','Es menos de lo que esperábamos.'],['Et si on trouvait un compromis à douze mille ?','¿Y si encontramos un acuerdo en doce mil?'],['D’accord, à condition que vous payiez sous trente jours.','De acuerdo, con la condición de que paguen en treinta días.'],['Ça me va. Pour résumer : douze mille en trente jours.','Me parece bien. Para resumir: doce mil en treinta días.']],
questions:[['¿Cuál es el precio final?','Doce mil','Diez mil','Treinta mil'],['¿Cuál es la condición?','Pagar en treinta días','Empezar en mayo','Más personal']],
drills:[['Propón con suavidad: on part demain →','Et si on partait demain ?'],['Completa: à condition que tu ___ (venir).','viennes'],['Escribe en francés: «Me parece bien.»','Ça me va.']],
write:{prompt:'Escribe un diálogo negociando vacaciones con tu jefa.',model:'— Je voudrais deux semaines en juillet. — C’est difficile. — Et si je prenais une semaine en juillet et une en août ? — Ça me va, à condition que tu finisses le rapport.'}},
{id:'fr-15',level:'B1+',title:'Medio ambiente y sociedad',goal:'hablar de problemas sociales con precisión.',
rule:'Causa: est dû à, provient de. Consecuencia: entraîne, provoque, conduit à. Solución: Il faudrait, Une solution serait de, Il est essentiel que + subjuntivo. Il faudrait suena a propuesta y no a orden. El adjetivo concuerda en lo escrito: une énergie renouvelable, des énergies renouvelables.',
items:[['Cela entraîne des températures plus élevées.','Esto provoca temperaturas más altas.'],['La pollution est due au trafic.','La contaminación se debe al tráfico.'],['Une solution serait de moins prendre l’avion.','Una solución sería volar menos.'],['Il est essentiel que nous agissions.','Es esencial que actuemos.'],['le changement climatique','el cambio climático'],['les énergies renouvelables','las energías renovables'],['les déchets','los residuos'],['la société','la sociedad']],
textTitle:'Une ville plus verte',text:[['La pollution de l’air est surtout due au trafic.','La contaminación del aire se debe sobre todo al tráfico.'],['Elle provoque de graves problèmes de santé, notamment chez les enfants.','Provoca graves problemas de salud, sobre todo en los niños.'],['Une solution serait d’investir dans les transports publics.','Una solución sería invertir en transporte público.'],['Plusieurs villes utilisent déjà des énergies renouvelables.','Varias ciudades ya usan energías renovables.'],['Il est essentiel que les citoyens participent.','Es esencial que los ciudadanos participen.']],
questions:[['¿A qué se debe la contaminación?','Al tráfico','A las fábricas','Al clima'],['¿A quién afecta más?','A los niños','A los conductores','A los ancianos']],
drills:[['Completa: Le retard est ___ à la grève.','dû'],['Escribe en francés: «Una solución sería reciclar más.»','Une solution serait de recycler plus.','Une solution serait de recycler davantage.'],['Completa: Il est essentiel que nous ___ (agir).','agissions']],
write:{prompt:'Explica un problema de tu ciudad: causa, efecto y solución.',model:'Dans ma ville, le problème principal est le trafic. Il est dû au manque de métro. Il provoque du stress. Une solution serait de construire une nouvelle ligne.'}},
{id:'fr-16',level:'B1+',title:'Tecnología y trabajo',goal:'debatir sobre tecnología.',
rule:'Presentar dos lados: D’un côté … de l’autre. Conceder: Même si + indicativo, cela dit, il n’en reste pas moins que. Tandis que y alors que contrastan dos hechos. Ne … que significa solo: Je n’ai que dix euros. Non seulement … mais aussi añade. Reste à savoir si… = está por ver si…',
items:[['D’un côté, c’est utile ; de l’autre, c’est cher.','Por un lado es útil; por otro, caro.'],['Même si c’est difficile, j’essaie.','Aunque es difícil, lo intento.'],['Je n’ai que dix euros.','Solo tengo diez euros.'],['Reste à savoir si cela marchera.','Está por ver si funcionará.'],['Non seulement c’est rapide, mais aussi économique.','No solo es rápido, sino también económico.'],['l’intelligence artificielle','la inteligencia artificial'],['une compétence','una competencia'],['remplacer','reemplazar']],
textTitle:'Machines et humains',text:[['D’un côté, l’automatisation rend les entreprises plus productives.','Por un lado, la automatización hace a las empresas más productivas.'],['De l’autre, elle menace de nombreux emplois.','Por otro, amenaza muchos empleos.'],['Les machines ne remplacent souvent que certaines tâches.','Las máquinas a menudo solo reemplazan ciertas tareas.'],['Il faut non seulement de nouvelles compétences, mais aussi du temps pour apprendre.','Hacen falta no solo nuevas competencias, sino también tiempo para aprender.'],['Reste à savoir si les gouvernements aideront.','Está por ver si los gobiernos ayudarán.']],
questions:[['¿Qué reemplazan las máquinas?','Ciertas tareas','Todo','Fábricas'],['¿Qué hace falta?','Competencias y tiempo','Más máquinas','Menos horas']],
drills:[['Escribe en francés: «Solo tengo una hora.»','Je n’ai qu’une heure.'],['Completa: Même si c’est cher, je l’___ (acheter, futuro).','achèterai'],['Escribe en francés: «por un lado»','d’un côté']],
write:{prompt:'Escribe un párrafo equilibrado: ¿la tecnología nos da más tiempo?',model:'D’un côté, la technologie nous fait gagner du temps. De l’autre, nous sommes toujours connectés. Même si c’est utile, je ne me repose jamais. Reste à savoir si cela changera.'}},
{id:'fr-17',level:'B1+',title:'Vida en Francia',goal:'entender trámites y costumbres.',
rule:'Para normas: il est interdit de, il est obligatoire de, on doit, on n’a pas le droit de. Il ne faut pas significa prohibición: Il ne faut pas fumer. No hace falta se dice ce n’est pas la peine de o pas besoin de. Esta diferencia es clave: il ne faut pas no significa «no es necesario», como parece.',
items:[['Il est interdit de fumer ici.','Está prohibido fumar aquí.'],['Il ne faut pas oublier.','No hay que olvidar.'],['Ce n’est pas la peine de venir.','No hace falta venir.'],['On n’a pas le droit d’entrer.','No se puede entrar.'],['la mairie','el ayuntamiento'],['le loyer','el alquiler'],['la Sécurité sociale','la seguridad social'],['un rendez-vous','una cita']],
textTitle:'S’installer en France',text:[['Quand on s’installe en France, il faut ouvrir un compte en banque.','Al instalarse en Francia hay que abrir una cuenta bancaria.'],['Pour louer un logement, on demande beaucoup de documents.','Para alquilar una vivienda piden muchos documentos.'],['Il est préférable de prendre rendez-vous avant d’aller à la mairie.','Es preferible pedir cita antes de ir al ayuntamiento.'],['Le dimanche, beaucoup de magasins sont fermés.','El domingo muchas tiendas están cerradas.'],['On dit toujours bonjour en entrant dans un magasin.','Siempre se saluda al entrar en una tienda.']],
questions:[['¿Qué se debe hacer al entrar en una tienda?','Saludar','Pagar','Pedir cita'],['¿Qué conviene antes de ir al ayuntamiento?','Pedir cita','Abrir una cuenta','Llevar dinero']],
drills:[['Elige: «No hace falta pagar.»','Ce n’est pas la peine de payer.','Pas besoin de payer.'],['Elige: «No hay que fumar.»','Il ne faut pas fumer.'],['Escribe en francés: «Está prohibido entrar.»','Il est interdit d’entrer.']],
write:{prompt:'Explica tres costumbres de tu país a un francés.',model:'Au Mexique, on mange tard. Il faut saluer les gens en arrivant. Ce n’est pas la peine d’être très formel avec les amis.'}},
{id:'fr-18',level:'B1+',title:'Gerundio y participios',goal:'acortar frases como en un texto escrito.',
rule:'En + -ant une dos acciones: J’ai appris en lisant. Sin en, el participio presente es formal y explica la causa: Étant malade, il reste chez lui. Ayant fini, elle part (tras terminar). No confundas con el adjetivo: une histoire intéressante concuerda, pero en travaillant no cambia nunca.',
items:[['J’ai appris en lisant.','Aprendí leyendo.'],['Étant malade, il reste chez lui.','Estando enfermo, se queda en casa.'],['Ayant fini, elle est partie.','Habiendo terminado, se fue.'],['En arrivant, j’ai vu Paul.','Al llegar, vi a Paul.'],['les personnes interrogées','las personas encuestadas'],['une étude','un estudio'],['les chercheurs','los investigadores'],['les résultats','los resultados']],
textTitle:'Une étude sur le sommeil',text:[['Des chercheurs travaillant à Lyon ont étudié deux mille adultes.','Unos investigadores que trabajan en Lyon estudiaron a dos mil adultos.'],['Les personnes dormant moins de six heures faisaient plus d’erreurs.','Las personas que dormían menos de seis horas cometían más errores.'],['Ayant analysé les données, l’équipe a publié ses résultats.','Tras analizar los datos, el equipo publicó sus resultados.'],['En dormant mieux, on travaille plus vite.','Durmiendo mejor se trabaja más rápido.'],['Le rapport, publié au printemps, a beaucoup attiré l’attention.','El informe, publicado en primavera, atrajo mucha atención.']],
questions:[['¿Quién cometía más errores?','Quienes dormían poco','Los investigadores','Los jóvenes'],['¿Cuándo se publicó?','En primavera','En invierno','Ayer']],
drills:[['Reduce: Quand je suis arrivé, j’ai vu Marie.','En arrivant, j’ai vu Marie.'],['Escribe en francés: «Aprendí escuchando.»','J’ai appris en écoutant.'],['Reduce: Comme il était fatigué, il est parti. → ___','Étant fatigué, il est parti.']],
write:{prompt:'Resume una noticia con al menos dos participios.',model:'Une étude publiée cette semaine montre que le sommeil est essentiel. Les personnes interrogées dorment mal. En dormant mieux, elles seraient plus heureuses.'}},
{id:'fr-19',level:'B1+',title:'Hablar como un francés',goal:'entender el francés coloquial real.',
rule:'En la calle se dice: ouais (sí), ça marche (vale), c’est pas grave, j’sais pas, t’as vu, y a. Palabras: une bagnole (coche), le boulot (trabajo), un mec (tipo), bosser (trabajar), sympa, super, truc (cosa). No las uses en escrito formal, pero las oirás todo el tiempo. Du coup significa entonces, y se abusa de él.',
items:[['Ça marche !','¡Vale!'],['C’est pas grave.','No pasa nada.'],['J’ai trop de boulot.','Tengo demasiado trabajo.'],['Du coup, on y va ?','Entonces, ¿vamos?'],['T’inquiète !','¡No te preocupes!'],['le truc','la cosa'],['le mec','el tipo'],['bosser','trabajar']],
textTitle:'Un message entre amis',text:[['Salut ! T’es libre ce soir ?','¡Hola! ¿Estás libre esta noche?'],['Ouais, mais j’ai trop de boulot, je finis tard.','Sí, pero tengo mucho trabajo, acabo tarde.'],['T’inquiète, on se voit à neuf heures.','No te preocupes, nos vemos a las nueve.'],['Ça marche ! Du coup, on mange où ?','¡Vale! Entonces, ¿dónde comemos?'],['Il y a un truc sympa près de chez moi.','Hay un sitio majo cerca de mi casa.']],
questions:[['¿A qué hora se ven?','A las nueve','A las ocho','Mañana'],['¿Por qué acaba tarde?','Tiene mucho trabajo','Está enfermo','Va a comer']],
drills:[['Hazlo formal: J’sais pas.','Je ne sais pas.'],['Hazlo formal: t’as vu ?','As-tu vu ?','Tu as vu ?'],['Da el coloquial de travail:','boulot','le boulot']],
write:{prompt:'Escribe un mensaje informal a un amigo para quedar.',model:'Salut ! Ça va ? T’es libre samedi ? On pourrait aller au ciné. Dis-moi, ça marche pour toi ?'}},
{id:'fr-20',level:'B1+',title:'Ensayo',goal:'escribir un texto largo con estructura.',
rule:'Un texto argumentativo: introducción con el tema, desarrollo con tesis y antítesis, conclusión. Conectores: Tout d’abord, De plus, En revanche, Pour conclure. Revisa al final: concordancia de participios, género, subjuntivo tras il faut que y bien que, y evita repetir je pense. Una idea por párrafo.',
items:[['Tout d’abord, il faut dire que…','Ante todo, hay que decir que…'],['De plus, le coût augmente.','Además, el coste aumenta.'],['En revanche, il y a des exceptions.','En cambio, hay excepciones.'],['Pour conclure, je suis pour.','Para concluir, estoy a favor.'],['la thèse','la tesis'],['convaincre','convencer'],['l’introduction','la introducción'],['la conclusion','la conclusión']],
textTitle:'Apprendre une langue adulte',text:[['Beaucoup d’adultes croient qu’il est trop tard pour apprendre une langue.','Muchos adultos creen que es tarde para aprender un idioma.'],['Tout d’abord, la recherche montre qu’ils apprennent très bien.','Ante todo, la investigación muestra que aprenden muy bien.'],['De plus, une nouvelle langue ouvre de nombreuses portes.','Además, un nuevo idioma abre muchas puertas.'],['En revanche, cela demande beaucoup de temps.','En cambio, exige mucho tiempo.'],['Pour conclure, les avantages me convainquent.','Para concluir, las ventajas me convencen.']],
questions:[['¿Qué muestra la investigación?','Los adultos aprenden bien','Es tarde','Solo los niños aprenden'],['¿Qué se exige?','Mucho tiempo','Mucho dinero','Un título']],
drills:[['Escribe en francés: «Además»','De plus','En outre'],['Escribe en francés: «En cambio»','En revanche','Par contre'],['Corrige: Il faut que tu viens.','Il faut que tu viennes.']],
write:{prompt:'Escribe 100 a 150 palabras: ¿debería ser gratis el transporte público?',model:'Beaucoup de gens demandent des transports gratuits. Tout d’abord, ce serait bon pour l’environnement, car il y aurait moins de voitures. De plus, les familles économiseraient de l’argent. En revanche, les villes devraient payer. Pour conclure, je suis pour, car les avantages sont plus importants.'}},
];

// Francés B2: precisión, registro y argumentación.
export const FRENCH_B2=[
{id:'fr-b2-01',level:'B2',title:'Contar con distancia',goal:'citar informaciones no confirmadas.',
rule:'La prensa francesa usa el condicional para lo no confirmado: Le ministre aurait démissionné (habría dimitido, según dicen). Otras fórmulas: selon, d’après, il semblerait que, prétendument. En passé: aurait + participio. No es una suposición tuya: es una forma de decir «no me hago responsable de esta información».',
items:[['Le ministre aurait démissionné.','El ministro habría dimitido.'],['Selon la police, il y aurait trois blessés.','Según la policía, habría tres heridos.'],['Il semblerait que l’accord soit signé.','Parecería que el acuerdo está firmado.'],['D’après nos sources, il partirait.','Según nuestras fuentes, se iría.'],['une rumeur','un rumor'],['démentir','desmentir'],['confirmer','confirmar']],
textTitle:'Un scandale',text:[['Le maire aurait utilisé l’argent de la ville pour des voyages privés.','El alcalde habría usado dinero municipal para viajes privados.'],['Lui-même affirme n’avoir rien su de ces paiements.','Él afirma no haber sabido nada de esos pagos.'],['Un employé aurait falsifié les factures.','Un empleado habría falsificado las facturas.'],['D’après la presse, la justice aurait déjà ouvert une enquête.','Según la prensa, la justicia ya habría abierto una investigación.'],['Pour l’instant, aucune confirmation officielle n’a été donnée.','Por ahora no se ha dado ninguna confirmación oficial.']],
questions:[['¿Qué afirma el alcalde?','Que no sabía nada','Que fue él','Que es un complot'],['¿Hay confirmación oficial?','No','Sí','A medias']],
drills:[['Hazlo no confirmado: Le président est malade.','Le président serait malade.'],['Hazlo no confirmado en pasado: Il est parti.','Il serait parti.'],['Escribe en francés: «según nuestras fuentes»','d’après nos sources','selon nos sources']],
write:{prompt:'Resume una noticia polémica marcando lo que no está confirmado.',model:'Un ministre aurait reçu de l’argent. Il affirme n’avoir rien su. Selon la presse, il y aurait des preuves.'}},
{id:'fr-b2-02',level:'B2',title:'Nominalizar',goal:'escribir con el estilo de un informe.',
rule:'El francés formal convierte verbos en nombres: Après avoir terminé le projet → Après la fin du projet. Parce qu’il pleuvait → En raison de la pluie. Si vous avez des questions → En cas de questions. Lors de, dès, suite à, avant, malgré van con nombre. Es más compacto y típico de cartas oficiales y prensa.',
items:[['Après la fin des travaux','Tras el fin de las obras'],['En cas de questions, contactez-nous.','En caso de preguntas, contáctenos.'],['En raison de la grève','Debido a la huelga'],['Lors de la réunion','Durante la reunión'],['Dès la réception du dossier','Desde la recepción del expediente'],['la mise en place','la puesta en marcha'],['le lancement','el lanzamiento']],
textTitle:'Un avis de l’entreprise',text:[['Après la fin des travaux, le bureau rouvrira lundi.','Tras el fin de las obras, la oficina reabrirá el lunes.'],['Lors de la mise en place du nouveau système, des retards sont possibles.','Durante la puesta en marcha del nuevo sistema, puede haber retrasos.'],['Malgré une préparation soigneuse, des problèmes ne sont pas exclus.','A pesar de una preparación cuidadosa, no se excluyen problemas.'],['En cas de questions techniques, contactez le service informatique.','En caso de preguntas técnicas, contacte con informática.'],['Dès la réception de votre demande, nous vous répondrons.','Desde que recibamos su solicitud, le responderemos.']],
questions:[['¿Cuándo reabre la oficina?','El lunes','Mañana','En un mes'],['¿A quién se dirigen las preguntas técnicas?','A informática','Al director','A recepción']],
drills:[['Nominaliza: Quand il est arrivé → À ___','À son arrivée'],['Nominaliza: Parce qu’il y avait du brouillard → En raison ___','En raison du brouillard'],['Nominaliza: Si on a un problème → En cas ___','En cas de problème']],
write:{prompt:'Escribe un aviso formal de tres frases con nominalizaciones.',model:'Après la fin des travaux, la bibliothèque rouvrira. En cas de questions, adressez-vous à l’accueil. Malgré les travaux, l’entrée reste accessible.'}},
{id:'fr-b2-03',level:'B2',title:'Conectores de nivel alto',goal:'argumentar con precisión.',
rule:'Para B2: d’autant plus que (tanto más cuanto que), dans la mesure où (en la medida en que), quitte à (aunque haya que), de sorte que (de modo que), pour peu que + subjuntivo (con tal de que), sous prétexte que (con el pretexto de que). Ainsi au début de frase invierte a menudo: Ainsi faut-il agir. Son señales de un nivel avanzado.',
items:[['C’est d’autant plus grave qu’il le savait.','Es tanto más grave cuanto que él lo sabía.'],['Dans la mesure où c’est possible, je viendrai.','En la medida de lo posible, vendré.'],['Je partirai, quitte à arriver en retard.','Me iré, aunque llegue tarde.'],['Il a parlé fort, de sorte que tous l’ont entendu.','Habló alto, de modo que todos lo oyeron.'],['Il refuse sous prétexte qu’il est fatigué.','Se niega con el pretexto de que está cansado.'],['pour peu que','con tal de que'],['en somme','en suma']],
textTitle:'Manger moins de viande ?',text:[['Beaucoup mangent moins de viande, d’autant plus que les prix ont augmenté.','Muchos comen menos carne, tanto más cuanto que los precios han subido.'],['Dans la mesure où l’on achète local, on protège aussi le climat.','En la medida en que se compra local, también se protege el clima.'],['Pour peu que la qualité soit bonne, beaucoup acceptent de payer plus.','Con tal de que la calidad sea buena, muchos aceptan pagar más.'],['Les plats végétariens progressent, de sorte que les restaurants adaptent leur carte.','Los platos vegetarianos avanzan, de modo que los restaurantes adaptan su carta.'],['Certains refusent tout changement, sous prétexte que c’est une mode.','Algunos rechazan todo cambio con el pretexto de que es una moda.']],
questions:[['¿Qué hacen los restaurantes?','Adaptan su carta','Cierran','Suben precios'],['¿Qué pretexto dan algunos?','Que es una moda','Que es caro','Que no saben cocinar']],
drills:[['Une con de sorte que: Il a plu. Le match a été annulé.','Il a plu, de sorte que le match a été annulé.'],['Completa: Pour peu qu’il ___ (faire) beau, on sortira.','fasse'],['Escribe en francés: «en la medida en que»','dans la mesure où']],
write:{prompt:'Explica cómo ahorrar en tu vida diaria con dos conectores de esta clase.',model:'On peut économiser en cuisinant soi-même, d’autant plus que c’est plus sain. Pour peu qu’on ait du temps, c’est aussi agréable.'}},
{id:'fr-b2-04',level:'B2',title:'Expresiones idiomáticas',goal:'entender modismos frecuentes.',
rule:'Los modismos no se traducen literalmente. Avoir le cafard: estar deprimido. Poser un lapin: dar plantón. Coûter les yeux de la tête: costar un ojo de la cara. Avoir un poil dans la main: ser vago. Mettre les pieds dans le plat: meter la pata. Ce n’est pas la mer à boire: no es para tanto. Úsalos con moderación.',
items:[['J’ai le cafard.','Estoy deprimido.'],['Il m’a posé un lapin.','Me dio plantón.'],['Ça coûte les yeux de la tête.','Cuesta un ojo de la cara.'],['J’ai mis les pieds dans le plat.','Metí la pata.'],['Ce n’est pas la mer à boire.','No es para tanto.'],['avoir un poil dans la main','ser vago'],['tomber dans les pommes','desmayarse']],
textTitle:'Une soirée ratée',text:[['Samedi, mon ami m’a posé un lapin au restaurant.','El sábado mi amigo me dio plantón en el restaurante.'],['J’ai attendu une heure et j’ai fini par commander seul.','Esperé una hora y acabé pidiendo solo.'],['Le repas coûtait les yeux de la tête.','La comida costaba un ojo de la cara.'],['Le lendemain, j’avais un peu le cafard.','Al día siguiente estaba algo deprimido.'],['Il s’est excusé, et finalement ce n’était pas la mer à boire.','Se disculpó, y al final no era para tanto.']],
questions:[['¿Qué le hizo su amigo?','Le dio plantón','Le robó','Llegó tarde'],['¿Cómo era la comida?','Muy cara','Barata','Mala']],
drills:[['Traduce: «Me dio plantón.»','Il m’a posé un lapin.','Elle m’a posé un lapin.'],['Traduce: «No es para tanto.»','Ce n’est pas la mer à boire.'],['¿Qué significa «avoir le cafard»?','estar deprimido']],
write:{prompt:'Cuenta un día malo usando dos modismos.',model:'Hier, j’ai mis les pieds dans le plat en parlant du salaire de ma collègue. Ensuite, j’ai eu le cafard toute la soirée.'}},
{id:'fr-b2-05',level:'B2',title:'Suponer en pasado',goal:'expresar suposiciones con futur antérieur y devoir.',
rule:'Para suponer sobre el pasado: futur antérieur (Il aura raté son train, habrá perdido el tren) o devoir en passé composé (Il a dû rater son train, debió de perderlo). En presente: Il doit être malade (debe de estar enfermo). Sans doute y probablement acompañan. Es la diferencia con el español «habrá…».',
items:[['Il aura raté son train.','Habrá perdido el tren.'],['Il a dû oublier.','Debió de olvidarlo.'],['Elle doit être malade.','Debe de estar enferma.'],['Ils seront partis tôt.','Se habrán ido temprano.'],['sans doute','sin duda, probablemente'],['une hypothèse','una hipótesis'],['supposer','suponer']],
textTitle:'Où est Paul ?',text:[['Paul n’est pas venu à la réunion.','Paul no vino a la reunión.'],['Il aura sans doute été bloqué dans les embouteillages.','Sin duda se habrá quedado atascado en el tráfico.'],['Ou bien il a dû oublier le rendez-vous.','O debió de olvidar la cita.'],['Sa collègue pense qu’il doit être malade.','Su colega piensa que debe de estar enfermo.'],['D’ici ce soir, il nous aura sûrement appelés.','Para esta noche seguramente nos habrá llamado.']],
questions:[['¿Qué cree su colega?','Que está enfermo','Que se fue de viaje','Que dimitió'],['¿Qué esperan para la noche?','Que llame','Que venga','Nada']],
drills:[['Supón con futur antérieur: Elle a oublié.','Elle aura oublié.'],['Supón con devoir: Il est parti.','Il a dû partir.'],['Escribe en francés: «Debe de estar cansado.»','Il doit être fatigué.']],
write:{prompt:'Un amigo no responde. Escribe tres suposiciones.',model:'Il aura perdu son téléphone. Il a dû s’endormir. Il doit être très occupé.'}},
{id:'fr-b2-06',level:'B2',title:'Hablar en público',goal:'estructurar una presentación oral.',
rule:'Fórmulas: Je vais vous parler de… Dans un premier temps…, dans un second temps…, enfin… Pour illustrer: Prenons l’exemple de… Para gráficos: Comme vous pouvez le constater sur ce graphique… Para cerrar: Pour conclure… Je vous remercie de votre attention. Usa vous con el público.',
items:[['Je vais vous parler de l’énergie.','Les voy a hablar de la energía.'],['Dans un premier temps, je présenterai les chiffres.','En primer lugar, presentaré las cifras.'],['Comme vous pouvez le constater…','Como pueden comprobar…'],['Prenons l’exemple de Lyon.','Tomemos el ejemplo de Lyon.'],['Pour conclure…','Para concluir…'],['Je vous remercie de votre attention.','Les agradezco su atención.'],['Avez-vous des questions ?','¿Tienen preguntas?']],
textTitle:'Une courte présentation',text:[['Je vais vous parler du télétravail.','Les voy a hablar del teletrabajo.'],['Dans un premier temps, je présenterai l’évolution des chiffres.','En primer lugar presentaré la evolución de las cifras.'],['Comme vous pouvez le constater, un salarié sur trois travaille en partie chez lui.','Como pueden comprobar, uno de cada tres empleados trabaja en parte en casa.'],['Dans un second temps, j’aborderai les avantages et les inconvénients.','En segundo lugar abordaré las ventajas y los inconvenientes.'],['Pour conclure, un système mixte semble idéal.','Para concluir, un sistema mixto parece ideal.']],
questions:[['¿Cuántos trabajan en parte desde casa?','Uno de cada tres','La mitad','Casi nadie'],['¿Qué conclusión da?','Un sistema mixto','Volver todos','Todos en casa']],
drills:[['Escribe en francés: «En primer lugar…»','Dans un premier temps','Dans un premier temps…','Tout d’abord'],['Escribe en francés: «Para concluir»','Pour conclure'],['Escribe en francés: «Les agradezco su atención.»','Je vous remercie de votre attention.']],
write:{prompt:'Prepara el guion de una presentación de un minuto sobre tu ciudad.',model:'Je vais vous parler de ma ville. Dans un premier temps, je présenterai son histoire. Ensuite, je vous montrerai ses plus beaux quartiers. Je vous remercie de votre attention.'}},
{id:'fr-b2-07',level:'B2',title:'Debate social',goal:'debatir un tema social complejo.',
rule:'Vocabulario: l’intégration, l’immigration, la diversité, l’égalité des chances, lutter contre les préjugés, le vivre-ensemble. Para matizar: On ne peut nier que… (no se puede negar que), Il serait faux de prétendre que… + subjuntivo, Force est de constater que (hay que reconocer que). Son marcas claras de B2.',
items:[['On ne peut nier qu’il y a des difficultés.','No se puede negar que hay dificultades.'],['Il serait faux de prétendre que tout aille mal.','Sería falso afirmar que todo va mal.'],['Force est de constater que la situation change.','Hay que reconocer que la situación cambia.'],['lutter contre les préjugés','luchar contra los prejuicios'],['l’égalité des chances','la igualdad de oportunidades'],['le vivre-ensemble','la convivencia'],['la diversité','la diversidad']],
textTitle:'L’intégration au quotidien',text:[['On ne peut nier que l’intégration demande du temps.','No se puede negar que la integración requiere tiempo.'],['Les cours de langue, à eux seuls, ne suffisent pas toujours.','Los cursos de idiomas por sí solos no siempre bastan.'],['Ce qui compte, ce sont les liens au travail, dans les associations et dans le quartier.','Lo que cuenta son los vínculos en el trabajo, en las asociaciones y en el barrio.'],['Il serait faux de prétendre que l’immigration n’apporte que des problèmes.','Sería falso afirmar que la inmigración solo trae problemas.'],['Force est de constater que de nombreux secteurs en dépendent.','Hay que reconocer que muchos sectores dependen de ella.']],
questions:[['¿Qué cuenta para integrarse?','Los vínculos cotidianos','Solo los cursos','Las leyes'],['¿Qué hay que reconocer?','Muchos sectores dependen de ella','No sirve','Es temporal']],
drills:[['Escribe en francés: «No se puede negar que…»','On ne peut nier que','On ne peut nier que…','On ne peut pas nier que'],['Escribe en francés: «la convivencia»','le vivre-ensemble'],['Escribe en francés: «luchar contra los prejuicios»','lutter contre les préjugés']],
write:{prompt:'¿Qué ayuda más a integrarse en un país nuevo? Escribe un párrafo equilibrado.',model:'On ne peut nier que la langue est essentielle. Il serait toutefois faux de prétendre qu’elle suffise. Force est de constater que les amitiés comptent autant.'}},
{id:'fr-b2-08',level:'B2',title:'El mundo del trabajo',goal:'manejarte en reuniones y evaluaciones.',
rule:'Expresiones fijas: respecter un délai (cumplir un plazo), prendre en charge (hacerse cargo), faire le point (hacer balance), en concertation avec (en concertación con), prendre acte (tomar nota), mettre en œuvre (poner en práctica). En una evaluación: Vos points forts sont…, Vous pourriez progresser en… Es lenguaje muy frecuente en empresas.',
items:[['Nous devons respecter le délai.','Debemos cumplir el plazo.'],['Je prends en charge ce dossier.','Me hago cargo de este expediente.'],['Faisons le point sur le projet.','Hagamos balance del proyecto.'],['en concertation avec la direction','en concertación con la dirección'],['Je prends acte de votre remarque.','Tomo nota de su observación.'],['mettre en œuvre','poner en práctica'],['Vos points forts sont l’organisation.','Sus puntos fuertes son la organización.']],
textTitle:'L’entretien annuel',text:[['Lors de l’entretien annuel, la directrice a félicité Anne.','En la entrevista anual la directora felicitó a Anne.'],['Ses points forts seraient surtout l’organisation et la rigueur.','Sus puntos fuertes serían sobre todo la organización y el rigor.'],['Elle pourrait toutefois progresser dans la relation avec les clients.','Podría, sin embargo, mejorar en la relación con los clientes.'],['Anne a pris acte de la remarque et a proposé une formation.','Anne tomó nota de la observación y propuso una formación.'],['En concertation avec les ressources humaines, la formation a été acceptée.','En concertación con recursos humanos, se aceptó la formación.']],
questions:[['¿En qué es fuerte Anne?','Organización y rigor','Ventas','Idiomas'],['¿Qué propuso?','Una formación','Un aumento','Un traslado']],
drills:[['Escribe en francés: «cumplir un plazo»','respecter un délai','respecter le délai'],['Escribe en francés: «Hagamos balance.»','Faisons le point.'],['Escribe en francés: «poner en práctica»','mettre en œuvre']],
write:{prompt:'Escribe tu propia evaluación: tus puntos fuertes y dónde puedes mejorar.',model:'Mes points forts sont le travail en équipe et la créativité. Je pourrais progresser dans la gestion du temps. Je compte mettre en œuvre un nouveau planning.'}},
{id:'fr-b2-09',level:'B2',title:'Literatura breve',goal:'leer y comentar un texto literario.',
rule:'Para comentar: Ce texte raconte…, Le personnage principal est…, L’atmosphère est mélancolique, L’auteur suggère que…, Ce texte invite à réfléchir sur… La literatura usa passé simple e imparfait; reconoce il fut, il dit, elle vit. Primero capta la idea general y luego los detalles.',
items:[['Ce texte raconte l’histoire d’un voyage.','Este texto cuenta la historia de un viaje.'],['Le personnage principal est un vieil homme.','El personaje principal es un anciano.'],['L’atmosphère est mélancolique.','El ambiente es melancólico.'],['Ce texte invite à réfléchir.','Este texto invita a reflexionar.'],['le narrateur','el narrador'],['le récit','el relato'],['suggérer','sugerir']],
textTitle:'Le quai',text:[['Chaque soir, le vieil homme s’asseyait sur le même banc du quai.','Cada noche el anciano se sentaba en el mismo banco del andén.'],['Il ne prenait jamais le train ; il regardait seulement partir les voyageurs.','Nunca tomaba el tren; solo miraba partir a los viajeros.'],['Un jour, un enfant lui demanda qui il attendait.','Un día un niño le preguntó a quién esperaba.'],['« Moi-même, répondit-il, celui que j’aurais pu devenir. »','«A mí mismo», respondió, «al que podría haber llegado a ser».'],['L’enfant ne comprit pas, mais il s’assit en silence à ses côtés.','El niño no entendió, pero se sentó en silencio a su lado.']],
questions:[['¿Qué hacía el anciano?','Miraba partir a los viajeros','Viajaba','Vendía billetes'],['¿A quién esperaba?','A sí mismo','A su hijo','A un tren concreto']],
drills:[['Da el passé composé de «il demanda»:','il a demandé'],['Da el passé composé de «il s’assit»:','il s’est assis'],['Escribe en francés: «el narrador»','le narrateur']],
write:{prompt:'Comenta el texto: de qué trata, cómo es el ambiente y qué te hace pensar.',model:'Ce texte raconte l’histoire d’un vieil homme qui attend sur un quai. L’atmosphère est mélancolique. Il invite à réfléchir sur les occasions manquées.'}},
{id:'fr-b2-10',level:'B2',title:'Precisión con preposiciones',goal:'evitar errores frecuentes de preposición.',
rule:'Errores típicos: dépendre de, s’intéresser à, penser à (pensar en), rêver de (soñar con), se marier avec, commencer à + infinitivo, essayer de, décider de, réussir à, se souvenir de. El español dice «pensar en» y «soñar con»; el francés, penser à y rêver de. Apréndelas siempre en bloque.',
items:[['Je pense à toi.','Pienso en ti.'],['Je rêve de voyager.','Sueño con viajar.'],['Il s’intéresse à la musique.','Le interesa la música.'],['Elle a réussi à finir.','Logró terminar.'],['J’ai décidé de partir.','Decidí irme.'],['Je me souviens de lui.','Me acuerdo de él.'],['Ça dépend de toi.','Depende de ti.']],
textTitle:'La candidature',text:[['Lucas rêve de travailler dans une banque.','Lucas sueña con trabajar en un banco.'],['Il s’intéresse surtout au conseil financier.','Le interesa sobre todo el asesoramiento financiero.'],['Il a décidé de postuler malgré la concurrence.','Decidió postularse pese a la competencia.'],['Il pense souvent à l’entretien et il essaie de rester calme.','Piensa a menudo en la entrevista e intenta mantener la calma.'],['Tout dépend maintenant de la décision du jury.','Ahora todo depende de la decisión del jurado.']],
questions:[['¿Con qué sueña Lucas?','Trabajar en un banco','Viajar','Ser profesor'],['¿De qué depende todo?','De la decisión del jurado','De su familia','Del dinero']],
drills:[['Completa: Je pense ___ mes vacances.','à'],['Completa: Il rêve ___ une maison.','d’'],['Completa: Elle a réussi ___ convaincre son chef.','à']],
write:{prompt:'Escribe cinco frases sobre tus planes con estos verbos y preposiciones.',model:'Je rêve de vivre à Lyon. Je m’intéresse à la cuisine. J’ai décidé d’apprendre le français et j’essaie de pratiquer chaque jour.'}},
{id:'fr-b2-11',level:'B2',title:'Carta al director',goal:'escribir una opinión pública convincente.',
rule:'Estructura: referencia (Dans votre article du…, vous affirmez que…), postura, dos argumentos, propuesta y cierre. Para reforzar: Je suis intimement convaincu que… Para conceder: Certes…, il n’en demeure pas moins que… Para proposer: Il serait judicieux que + subjuntivo. Registro formal pero personal.',
items:[['Dans votre article, vous affirmez que…','En su artículo, usted afirma que…'],['Je suis intimement convaincu que…','Estoy íntimamente convencido de que…'],['Il serait judicieux que la ville agisse.','Sería juicioso que la ciudad actuara.'],['Certes…, il n’en demeure pas moins que…','Es cierto que…, pero no deja de ser cierto que…'],['le courrier des lecteurs','las cartas de los lectores'],['une revendication','una reivindicación'],['judicieux','juicioso']],
textTitle:'Courrier des lecteurs',text:[['Dans votre article du 3 mai, vous affirmez que les pistes cyclables coûtent trop cher.','En su artículo del 3 de mayo afirma que los carriles bici cuestan demasiado.'],['Je suis intimement convaincu du contraire.','Estoy íntimamente convencido de lo contrario.'],['Certes, elles ont un coût, il n’en demeure pas moins qu’elles désengorgent les rues.','Es cierto que tienen un coste, pero no deja de ser cierto que descongestionan las calles.'],['De plus, elles améliorent la santé des habitants.','Además, mejoran la salud de los vecinos.'],['Il serait judicieux que la ville investisse davantage.','Sería juicioso que la ciudad invirtiera más.']],
questions:[['¿Qué afirmaba el artículo?','Que los carriles bici son caros','Que hay que construir más','Que el tráfico baja'],['¿Qué propone el autor?','Invertir más','Prohibir bicicletas','Nada']],
drills:[['Completa: Il serait judicieux que la ville ___ (agir).','agisse'],['Escribe en francés: «Estoy íntimamente convencido de que…»','Je suis intimement convaincu que','Je suis intimement convaincu que…','Je suis intimement convaincue que'],['Escribe en francés: «las cartas de los lectores»','le courrier des lecteurs']],
write:{prompt:'Escribe una carta al director de 100 palabras sobre un tema de tu ciudad.',model:'Dans votre article, vous affirmez que le parc doit fermer. Je suis intimement convaincu que ce serait une erreur. Certes, son entretien coûte cher, il n’en demeure pas moins qu’il est essentiel pour les familles. Il serait judicieux que la ville trouve une autre solution.'}},
{id:'fr-b2-12',level:'B2',title:'Debate final',goal:'defender y rebatir posturas en un debate.',
rule:'Rebatir con cortesía: Permettez-moi de ne pas être d’accord. Je ne partage pas votre avis. Votre argument ne me convainc pas, car… Conceder: Vous n’avez pas tout à fait tort. Volver a tu punto: Il n’empêche que… (eso no quita que). Ganar tiempo: C’est une bonne question. El condicional suaviza: Je dirais plutôt que…',
items:[['Permettez-moi de ne pas être d’accord.','Permítame no estar de acuerdo.'],['Je ne partage pas votre avis.','No comparto su opinión.'],['Votre argument ne me convainc pas.','Su argumento no me convence.'],['Vous n’avez pas tout à fait tort.','No le falta del todo razón.'],['Il n’empêche que…','Eso no quita que…'],['Je dirais plutôt que…','Yo diría más bien que…'],['une objection','una objeción']],
textTitle:'Les réseaux sociaux à partir de 16 ans ?',text:[['A : À mon avis, les réseaux sociaux devraient être interdits avant 16 ans.','A: En mi opinión, las redes deberían prohibirse antes de los 16.'],['B : Permettez-moi de ne pas être d’accord, ce serait impossible à contrôler.','B: Permítame no estar de acuerdo, sería imposible de controlar.'],['A : Vous n’avez pas tout à fait tort, mais une règle envoie un signal.','A: No le falta del todo razón, pero una norma envía una señal.'],['B : Votre argument ne me convainc pas, car l’éducation compte plus que l’interdiction.','B: Su argumento no me convence, porque la educación importa más que la prohibición.'],['A : Il n’empêche que nous devons protéger les enfants.','A: Eso no quita que debamos proteger a los niños.']],
questions:[['¿Qué propone A?','Prohibir antes de los 16','Prohibir del todo','Nada'],['¿Qué prefiere B?','La educación','Más prohibiciones','Lo mismo que A']],
drills:[['Escribe en francés: «No comparto su opinión.»','Je ne partage pas votre avis.'],['Escribe en francés: «Eso no quita que…»','Il n’empêche que','Il n’empêche que…'],['Escribe en francés: «Yo diría más bien que…»','Je dirais plutôt que','Je dirais plutôt que…']],
write:{prompt:'Escribe un debate breve contigo mismo: una postura, una objeción y tu respuesta.',model:'Je pense que la viande devrait coûter plus cher. On pourrait objecter que les familles modestes en souffriraient. Vous n’avez pas tout à fait tort, il n’empêche que l’environnement doit passer en premier.'}},
];
